using System;
using System.IO;
using System.Linq;
namespace Touchfish {
public partial class PanelWindow {
 public void PreviewHighCostScope(string folder){previewRun=true;Directory.CreateDirectory(folder);int before=checks;Check(catalog.Deckable(catalog.Pool("classic-2014")).Where(c=>c.Cost==5||c.Cost==6).All(matchRules.Supports),"Five/six mana pool supported");VerifyHighCostTcp(folder);File.WriteAllText(Path.Combine(folder,"high-cost-verification.txt"),"PASS: "+(checks-before)+" checks; real loopback TCP, Faceless copy identity, Black Knight target, private power chords, invention trigger and Illidan board cap.");}
 int InjectHighAux(MatchEngine g,string id,int seat){int instance=g.NewEffectInstanceId();g.Players[seat].Hand.Add(new HandCard{Id=instance,CardId=id,Generated=true});return instance;}
 void VerifyHighCostTcp(string folder){if(!VerificationRun.Network)return;LeaveLan();ApplyTheme(true,true);ApplyMode(false);SetFullEffects(false);var guest=new PanelWindow(true){ShowInTaskbar=false,Opacity=0};guest.Show();guest.ApplyTheme(true,true);guest.ApplyMode(false);try{
  lanPort.Text=FreeLanPort().ToString();lanDeck.SelectedIndex=0;lanClass.SelectedItem=Classes.First(c=>c.Key=="MAGE");BeginLan(true);guest.lanDeck.SelectedIndex=0;guest.lanClass.SelectedItem=Classes.First(c=>c.Key=="MAGE");guest.lanAddress.Text="127.0.0.1:"+lanPort.Text;guest.BeginLan(false);PumpLan(()=>lanReady&&guest.lanReady,"High cost peers connect");DoMatch("mulligan",selectedIds:new int[0]);PumpLan(()=>guest.match.Players[0].MulliganDone,"High cost host mulligan");guest.DoMatch("mulligan",selectedIds:new int[0]);PumpLan(()=>match.MulliganComplete&&!guest.lanWaiting,"High cost mulligans done");var g=lanAuthority.Game;foreach(var p in g.Players){p.Hand.Clear();p.Board.Clear();p.Mana=p.MaxMana=10;}var original=g.Summon(1,"VAN_CS2_179");original.BuffAttack=2;original.DamageTaken=1;original.ForestDeathrattles=1;int faceless=Inject(g,"EX1_564"),etc=Inject(g,"PRO_001");PublishLan();BeginCard(faceless);ClickEmptySlot(0,0);Check(pending=="play","Faceless asks target after position");ClickMatchTarget(new MatchTarget(1,original.Id));PumpLan(()=>guest.match.Players[0].Board.Any(u=>u.CardId=="VAN_CS2_179"),"Faceless copied card synchronized");var copy=g.Players[0].Board.Single();Check(copy.Id!=original.Id&&guest.match.Players[0].Board.Single().Owner==0&&guest.match.Players[0].Board.Single().Health==4&&guest.match.Players[0].Board.Single().ForestDeathrattles==1,"Copy identity stats and enchantment match public snapshot");BeginCard(etc);ClickEmptySlot(0,1);PumpLan(()=>guest.match.Players[1].Hand.Count==1&&HighCostRules.Chords.Contains(guest.match.Players[1].Hand.Single().CardId),"Guest private chord arrives");Check(HighCostRules.Chords.Contains(g.Players[0].Hand.Single().CardId)&&guest.match.Players[0].Hand.Count==0&&LanProtocol.View(g,0,"high",1).Players[1].Hand.Length==0,"Power chord cards masked from opposite seat");Render(Path.Combine(folder,"141-high-cost-copy-chords-codex.png"));DoMatch("end");PumpLan(()=>guest.match.Active==1,"Guest high cost turn");
  g.Players[1].Mana=10;int knight=Inject(g,"EX1_002",1);PublishLan();PumpLan(()=>guest.match.Players[1].Hand.Any(h=>h.Id==knight),"Guest Black Knight received");guest.BeginCard(knight);guest.ClickEmptySlot(1,1);guest.ClickMatchTarget(new MatchTarget(0,copy.Id));PumpLan(()=>!guest.lanWaiting&&g.Players[0].Board.All(u=>u.Id!=copy.Id),"Black Knight destroys copied Taunt");PumpLan(()=>guest.match.Players[0].Board.All(u=>u.Id!=copy.Id),"Copied unit death and attached deathrattle synchronize");Check(g.Players[0].Board.Count==2&&g.Players[0].Board.Count(u=>u.CardId=="VAN_PRO_001")==1&&g.Players[0].Board.Any(u=>u.BaseAttack==2&&u.BaseHealth==2),"Copied forest deathrattle summons one tree alongside ETC");
  foreach(var p in g.Players){p.Hand.Clear();p.Board.Clear();p.Mana=10;}var auction=g.Summon(1,"VAN_EX1_095");int damage=InjectHighAux(g,"GAME_ROGUES_DO_IT",1);PublishLan();PumpLan(()=>guest.match.Players[1].Hand.Any(h=>h.Id==damage),"Generated damage chord visible to owner");int beforeHealth=g.Players[0].Health;guest.BeginCard(damage);guest.ClickMatchTarget(new MatchTarget(0));PumpLan(()=>!guest.lanWaiting&&guest.match.Players[1].Hand.Count==2,"Auctioneer plus chord each draw privately");Check(g.Players[0].Health==beforeHealth-4&&LanProtocol.View(g,0,"high",1).Players[1].Hand.Length==0,"Damage and private draws authoritative");guest.Opacity=1;guest.Render(Path.Combine(folder,"142-high-cost-auctioneer-codex.png"));guest.Opacity=0;
  g.Players[1].Hand.Clear();g.Players[1].Board.Clear();g.Players[1].Mana=10;g.Summon(1,"VAN_EX1_614");for(int n=0;n<5;n++)g.Summon(1,"VAN_CS2_231");int blade=Inject(g,"CS2_181",1);PublishLan();PumpLan(()=>guest.match.Players[1].Hand.Any(h=>h.Id==blade),"Guest seventh slot minion received");guest.BeginCard(blade);guest.ClickEmptySlot(1,6);PumpLan(()=>!guest.lanWaiting&&g.Players[1].Board.Count==7,"Illidan permits played seventh minion");Check(g.Players[1].Board.Last().CardId=="VAN_CS2_181"&&g.Players[1].Board.Last().Health==3,"Seventh slot stays Blademaster and battlecry completes");
  g.Players[0].Board.Clear();g.Players[0].Hand.Clear();var chicken=g.Summon(0,"GAME_HOMING_CHICKEN");PublishLan();PumpLan(()=>guest.match.Players[0].Board.Any(u=>u.Id==chicken.Id),"Invention appears in public board");guest.DoMatch("end");PumpLan(()=>!guest.lanWaiting&&guest.match.Active==0&&guest.match.Players[0].Board.All(u=>u.Id!=chicken.Id),"Homing Chicken next turn resolves on host");Check(g.Players[0].Hand.Count==4&&guest.match.Players[0].Hand.Count==0,"Three invention draws plus normal turn draw remain private");
 }finally{guest.LeaveLan();guest.Close();LeaveLan();}}
}
